sys_script.script:
(function executeRule(current, previous /* null when async */ ) {

    var fieldSysId = current.getValue('field_from_task');
    var targetApp = current.getValue('u_target_app'); // Get the value of u_target_app field

    if (!fieldSysId) {
        current.from_table = 'unknown';
        current.update();
        return;
    }

    var dictGR = new GlideRecord('sys_dictionary');
    if (dictGR.get(fieldSysId)) {
        var fieldName = dictGR.getValue('element');

        // Check if u_target_app is 'cash_equity'
        if (targetApp == 'cash_equity') {
            // Check if the column name matches one of the specified value
            var cashEquityFields = [
                'u_ctac_trade_audit_0_buy_sell_s',
                'u_value_date',
                'u_ctac_trade_audit_0_gross_consideration_f64',
                'u_trade_date',
                'u_trade_status',
                'u_ctac_trade_audit_0_counterparty_code_s',
                'stock_connect_trade'
            ];
            if (fieldName == 'stock_connect_trade') {
                current.from_table = 'x_hsb11_hsbc_mss_t_trade_case';
            } else {
                if (cashEquityFields.indexOf(fieldName) !== -1) {
                    current.from_table = 'sn_bom_trade';
                } else if (new GlideRecord('x_hsb11_hsbc_mss_t_trade_task').isValidField(fieldName)) {
                    current.from_table = 'x_hsb11_hsbc_mss_t_trade_task';
                } else {
                    current.from_table = 'unknown';
                }
            }
        }
        // Check if u_target_app is 'mss_custody' and apply the logic
        else if (targetApp == 'mss_custody') {
            if (new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task').isValidField(fieldName)) {
                current.from_table = 'x_hsb11_mss_c_proc_mss_custody_task';
            } else if (new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade').isValidField(fieldName)) {
                current.from_table = 'x_hsb11_mss_c_proc_mss_custody_trade';
            } else if (new GlideRecord('u_financial_trade_task').isValidField(fieldName)) {
                current.from_table = 'financial_trade_task';
            } else {
                current.from_table = 'unknown';
            }
        }
        // Default case for unsupported u_target_app values
        else {
            current.from_table = 'unknown';
        }

        // Save changes since this is After/Async BR
        current.update();

    } else {
        current.from_table = 'unknown';
        current.update();
    }

})(current, previous);
